namespace TutorFlow.Application.Llm;

/// <summary>
/// El proveedor LLM no esta disponible o rechazo la credencial (401/403, reintentos agotados, salida ilegible).
/// Core la mapea a 503 (SPEC 10.2). El mensaje nunca contiene la llave ni el cuerpo del proveedor.
/// </summary>
public sealed class LlmNoDisponibleException : Exception
{
    public LlmNoDisponibleException(string message, int? statusCode = null, Exception? inner = null)
        : base(message, inner)
    {
        StatusCode = statusCode;
    }

    /// <summary>Ultimo codigo HTTP del proveedor, si lo hubo.</summary>
    public int? StatusCode { get; }
}

/// <summary>Configuracion LLM invalida (p. ej. LLM_PROVIDER desconocido). Debe fallar al arrancar.</summary>
public sealed class LlmConfiguracionException(string message) : InvalidOperationException(message);

using System.Globalization;

namespace TutorFlow.Application.Llm;

public static class LlmProviders
{
    public const string Anthropic = "anthropic";
    public const string OpenAiCompatible = "openai-compatible";
}

/// <summary>Configuracion del proveedor LLM (SPEC 11). <see cref="ApiKey"/> jamas se imprime.</summary>
public sealed record LlmOptions
{
    public const string DefaultModel = "claude-haiku-5-5";
    public const int DefaultMaxTokensPerRequest = 8000;
    public const string DefaultAnthropicBaseUrl = "https://api.anthropic.com";
    public const string DefaultOpenAiBaseUrl = "https://api.openai.com/v1";

    public string Provider { get; init; } = LlmProviders.Anthropic;

    public string Model { get; init; } = DefaultModel;

    public string? BaseUrl { get; init; }

    public string? ApiKey { get; init; }

    public int MaxTokensPerRequest { get; init; } = DefaultMaxTokensPerRequest;

    public decimal PrecioEntradaPorMtok { get; init; }

    public decimal PrecioSalidaPorMtok { get; init; }

    // Evita que la llave salga por ToString() del record.
    public override string ToString() => $"LlmOptions(Provider={Provider}, Model={Model})";

    /// <summary>Lee LLM_PROVIDER, LLM_MODEL, LLM_BASE_URL, LLM_API_KEY, LLM_MAX_TOKENS_PER_REQUEST y los precios.</summary>
    public static LlmOptions FromConfig(Func<string, string?> get)
    {
        ArgumentNullException.ThrowIfNull(get);
        var provider = (Valor(get("LLM_PROVIDER")) ?? LlmProviders.Anthropic).ToLowerInvariant();
        if (provider is not (LlmProviders.Anthropic or LlmProviders.OpenAiCompatible))
        {
            throw new LlmConfiguracionException(
                $"LLM_PROVIDER '{provider}' no es valido. Valores admitidos: {LlmProviders.Anthropic} | {LlmProviders.OpenAiCompatible}.");
        }

        return new LlmOptions
        {
            Provider = provider,
            Model = Valor(get("LLM_MODEL")) ?? DefaultModel,
            BaseUrl = Valor(get("LLM_BASE_URL")),
            ApiKey = Valor(get("LLM_API_KEY")),
            MaxTokensPerRequest = Entero(get("LLM_MAX_TOKENS_PER_REQUEST"), "LLM_MAX_TOKENS_PER_REQUEST", DefaultMaxTokensPerRequest),
            PrecioEntradaPorMtok = Decimal(get("LLM_PRICE_INPUT_PER_MTOK"), "LLM_PRICE_INPUT_PER_MTOK"),
            PrecioSalidaPorMtok = Decimal(get("LLM_PRICE_OUTPUT_PER_MTOK"), "LLM_PRICE_OUTPUT_PER_MTOK"),
        };
    }

    private static string? Valor(string? v) => string.IsNullOrWhiteSpace(v) ? null : v.Trim();

    private static int Entero(string? v, string nombre, int porDefecto)
    {
        if (Valor(v) is not { } s)
        {
            return porDefecto;
        }

        if (!int.TryParse(s, NumberStyles.Integer, CultureInfo.InvariantCulture, out var n) || n < 1)
        {
            throw new LlmConfiguracionException($"{nombre} debe ser un entero positivo.");
        }

        return n;
    }

    private static decimal Decimal(string? v, string nombre)
    {
        if (Valor(v) is not { } s)
        {
            return 0m;
        }

        if (!decimal.TryParse(s, NumberStyles.Number, CultureInfo.InvariantCulture, out var d) || d < 0)
        {
            throw new LlmConfiguracionException($"{nombre} debe ser un decimal no negativo (punto decimal).");
        }

        return d;
    }
}

using System.Net;
using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
using TutorFlow.Application.Ports;

namespace TutorFlow.Application.Llm;

/// <summary>
/// Base de los adaptadores HTTP: timeout de 20 s por intento, 2 reintentos ante 429/5xx/red respetando retry-after,
/// sin reintento ante 401/403. La llave solo viaja en la cabecera; nunca en logs ni en excepciones.
/// El HttpClient lo aporta Infrastructure (o las pruebas con respuestas grabadas).
/// </summary>
public abstract class HttpLlmClientBase : ILlmClient
{
    public const int MaxReintentos = 2;
    public static readonly TimeSpan TimeoutPorIntento = TimeSpan.FromSeconds(20);
    public static readonly TimeSpan TopeRetryAfter = TimeSpan.FromSeconds(10);

    private readonly HttpClient _http;
    private readonly Action<string>? _log;
    private readonly Func<TimeSpan, CancellationToken, Task> _delay;

    protected HttpLlmClientBase(
        HttpClient http,
        LlmOptions options,
        Action<string>? log = null,
        Func<TimeSpan, CancellationToken, Task>? delay = null)
    {
        _http = http ?? throw new ArgumentNullException(nameof(http));
        Options = options ?? throw new ArgumentNullException(nameof(options));
        _log = log;
        _delay = delay ?? Task.Delay;
    }

    protected LlmOptions Options { get; }

    protected abstract string Endpoint { get; }

    protected abstract string BuildBody(LlmRequest solicitud);

    protected abstract void ApplyAuth(HttpRequestMessage request, string apiKey);

    protected abstract LlmResponse ParseResponse(string json);

    public async Task<LlmResponse> CompletarAsync(LlmRequest solicitud, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(solicitud);
        if (string.IsNullOrWhiteSpace(Options.ApiKey))
        {
            _log?.Invoke("Configuracion LLM: LLM_API_KEY no esta definida.");
            throw new LlmNoDisponibleException("LLM_API_KEY no esta configurada.");
        }

        var body = BuildBody(solicitud);
        int? ultimoEstado = null;
        for (var intento = 0; intento <= MaxReintentos; intento++)
        {
            TimeSpan? retryAfter = null;
            try
            {
                using var request = new HttpRequestMessage(HttpMethod.Post, Endpoint)
                {
                    Content = new StringContent(body, Encoding.UTF8, "application/json"),
                };
                ApplyAuth(request, Options.ApiKey);
                using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
                cts.CancelAfter(TimeoutPorIntento);
                using var response = await _http.SendAsync(request, cts.Token).ConfigureAwait(false);
                var status = (int)response.StatusCode;
                ultimoEstado = status;
                var texto = await response.Content.ReadAsStringAsync(cts.Token).ConfigureAwait(false);

                if (response.IsSuccessStatusCode)
                {
                    try
                    {
                        return ParseResponse(texto);
                    }
                    catch (Exception ex) when (ex is JsonException or InvalidOperationException or KeyNotFoundException or FormatException)
                    {
                        throw new LlmNoDisponibleException($"Respuesta ilegible del proveedor '{Options.Provider}'.", status, ex);
                    }
                }

                if (response.StatusCode is HttpStatusCode.Unauthorized or HttpStatusCode.Forbidden)
                {
                    _log?.Invoke($"Error de configuracion LLM: el proveedor '{Options.Provider}' rechazo la credencial (HTTP {status}).");
                    throw new LlmNoDisponibleException($"El proveedor '{Options.Provider}' rechazo la credencial (HTTP {status}).", status);
                }

                if (status != 429 && status < 500)
                {
                    _log?.Invoke($"El proveedor '{Options.Provider}' rechazo la solicitud (HTTP {status}).");
                    throw new LlmNoDisponibleException($"El proveedor '{Options.Provider}' rechazo la solicitud (HTTP {status}).", status);
                }

                retryAfter = LeerRetryAfter(response.Headers);
            }
            catch (OperationCanceledException) when (ct.IsCancellationRequested)
            {
                throw;
            }
            catch (OperationCanceledException)
            {
                ultimoEstado = null;
                _log?.Invoke($"Timeout de {TimeoutPorIntento.TotalSeconds:0} s del proveedor '{Options.Provider}'.");
            }
            catch (HttpRequestException)
            {
                ultimoEstado = null;
                _log?.Invoke($"Fallo de red hacia el proveedor '{Options.Provider}'.");
            }

            if (intento < MaxReintentos)
            {
                var espera = retryAfter ?? TimeSpan.FromMilliseconds(500 * (intento + 1));
                _log?.Invoke($"Reintento {intento + 1}/{MaxReintentos} del proveedor '{Options.Provider}' en {espera.TotalSeconds:0.###} s.");
                await _delay(espera, ct).ConfigureAwait(false);
            }
        }

        throw new LlmNoDisponibleException(
            $"El proveedor '{Options.Provider}' no respondio tras {MaxReintentos + 1} intentos.",
            ultimoEstado);
    }

    private static TimeSpan? LeerRetryAfter(HttpResponseHeaders headers)
    {
        var ra = headers.RetryAfter;
        if (ra is null)
        {
            return null;
        }

        TimeSpan? valor = ra.Delta ?? (ra.Date is { } d ? d - DateTimeOffset.UtcNow : null);
        if (valor is null)
        {
            return null;
        }

        if (valor < TimeSpan.Zero)
        {
            return TimeSpan.Zero;
        }

        return valor > TopeRetryAfter ? TopeRetryAfter : valor;
    }

    /// <summary>Convencion de mensajes: Asistente + InvocacionId = propuesta de herramienta (Contenido = argumentos JSON).</summary>
    protected static bool EsInvocacionAsistente(LlmMensaje m) =>
        m.Rol == RolMensaje.Asistente && m.InvocacionId is not null && m.NombreHerramienta is not null;

    protected static JsonElement ArgumentosComoJson(string contenido)
    {
        try
        {
            using var doc = JsonDocument.Parse(string.IsNullOrWhiteSpace(contenido) ? "{}" : contenido);
            return doc.RootElement.Clone();
        }
        catch (JsonException)
        {
            using var doc = JsonDocument.Parse("{}");
            return doc.RootElement.Clone();
        }
    }
}

using System.Text;
using System.Text.Json;
using TutorFlow.Application.Ports;

namespace TutorFlow.Application.Llm;

/// <summary>Adaptador de la Messages API de Anthropic con herramientas. Temperatura 0.</summary>
public sealed class AnthropicLlmClient(
    HttpClient http,
    LlmOptions options,
    Action<string>? log = null,
    Func<TimeSpan, CancellationToken, Task>? delay = null) : HttpLlmClientBase(http, options, log, delay)
{
    private const string Version = "2023-06-01";

    protected override string Endpoint =>
        (Options.BaseUrl ?? LlmOptions.DefaultAnthropicBaseUrl).TrimEnd('/') + "/v1/messages";

    protected override void ApplyAuth(HttpRequestMessage request, string apiKey)
    {
        request.Headers.Add("x-api-key", apiKey);
        request.Headers.Add("anthropic-version", Version);
    }

    protected override string BuildBody(LlmRequest r)
    {
        using var ms = new MemoryStream();
        using (var w = new Utf8JsonWriter(ms))
        {
            w.WriteStartObject();
            w.WriteString("model", Options.Model);
            w.WriteNumber("max_tokens", r.MaxTokens);
            w.WriteNumber("temperature", 0);
            w.WriteString("system", r.Sistema);
            w.WriteStartArray("messages");
            var msgs = r.Mensajes;
            for (var i = 0; i < msgs.Count;)
            {
                var m = msgs[i];
                if (EsInvocacionAsistente(m))
                {
                    w.WriteStartObject();
                    w.WriteString("role", "assistant");
                    w.WriteStartArray("content");
                    while (i < msgs.Count && EsInvocacionAsistente(msgs[i]))
                    {
                        w.WriteStartObject();
                        w.WriteString("type", "tool_use");
                        w.WriteString("id", msgs[i].InvocacionId);
                        w.WriteString("name", msgs[i].NombreHerramienta);
                        w.WritePropertyName("input");
                        ArgumentosComoJson(msgs[i].Contenido).WriteTo(w);
                        w.WriteEndObject();
                        i++;
                    }

                    w.WriteEndArray();
                    w.WriteEndObject();
                }
                else if (m.Rol == RolMensaje.Herramienta)
                {
                    w.WriteStartObject();
                    w.WriteString("role", "user");
                    w.WriteStartArray("content");
                    while (i < msgs.Count && msgs[i].Rol == RolMensaje.Herramienta)
                    {
                        w.WriteStartObject();
                        w.WriteString("type", "tool_result");
                        w.WriteString("tool_use_id", msgs[i].InvocacionId);
                        w.WriteString("content", msgs[i].Contenido);
                        w.WriteEndObject();
                        i++;
                    }

                    w.WriteEndArray();
                    w.WriteEndObject();
                }
                else
                {
                    w.WriteStartObject();
                    w.WriteString("role", m.Rol == RolMensaje.Asistente ? "assistant" : "user");
                    w.WriteString("content", m.Contenido);
                    w.WriteEndObject();
                    i++;
                }
            }

            w.WriteEndArray();
            if (r.Herramientas.Count > 0)
            {
                w.WriteStartArray("tools");
                foreach (var t in r.Herramientas)
                {
                    w.WriteStartObject();
                    w.WriteString("name", t.Nombre);
                    w.WriteString("description", t.Descripcion);
                    w.WritePropertyName("input_schema");
                    t.EsquemaArgumentos.WriteTo(w);
                    w.WriteEndObject();
                }

                w.WriteEndArray();
            }

            w.WriteEndObject();
        }

        return Encoding.UTF8.GetString(ms.ToArray());
    }

    protected override LlmResponse ParseResponse(string json)
    {
        using var doc = JsonDocument.Parse(json);
        var root = doc.RootElement;
        var texto = new StringBuilder();
        var invocaciones = new List<InvocacionPropuesta>();
        if (root.TryGetProperty("content", out var content) && content.ValueKind == JsonValueKind.Array)
        {
            foreach (var b in content.EnumerateArray())
            {
                var tipo = b.GetProperty("type").GetString();
                if (tipo == "text")
                {
                    texto.Append(b.GetProperty("text").GetString());
                }
                else if (tipo == "tool_use")
                {
                    var input = b.TryGetProperty("input", out var inp) ? inp.Clone() : ArgumentosComoJson("{}");
                    invocaciones.Add(new InvocacionPropuesta(
                        b.TryGetProperty("id", out var id) ? id.GetString() : null,
                        b.GetProperty("name").GetString() ?? string.Empty,
                        input));
                }
            }
        }

        var usage = root.GetProperty("usage");
        var entrada = Int(usage, "input_tokens") + Int(usage, "cache_creation_input_tokens") + Int(usage, "cache_read_input_tokens");
        return new LlmResponse(texto.ToString(), invocaciones, new UsoTokens(entrada, Int(usage, "output_tokens")));
    }

    private static int Int(JsonElement e, string name) =>
        e.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.Number ? v.GetInt32() : 0;
}

using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
using TutorFlow.Application.Ports;

namespace TutorFlow.Application.Llm;

/// <summary>Adaptador de chat completions con herramientas (OpenAI, Ollama, LM Studio...). Temperatura 0.</summary>
public sealed class OpenAiCompatibleLlmClient(
    HttpClient http,
    LlmOptions options,
    Action<string>? log = null,
    Func<TimeSpan, CancellationToken, Task>? delay = null) : HttpLlmClientBase(http, options, log, delay)
{
    protected override string Endpoint =>
        (Options.BaseUrl ?? LlmOptions.DefaultOpenAiBaseUrl).TrimEnd('/') + "/chat/completions";

    protected override void ApplyAuth(HttpRequestMessage request, string apiKey) =>
        request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", apiKey);

    protected override string BuildBody(LlmRequest r)
    {
        using var ms = new MemoryStream();
        using (var w = new Utf8JsonWriter(ms))
        {
            w.WriteStartObject();
            w.WriteString("model", Options.Model);
            w.WriteNumber("max_tokens", r.MaxTokens);
            w.WriteNumber("temperature", 0);
            w.WriteStartArray("messages");
            w.WriteStartObject();
            w.WriteString("role", "system");
            w.WriteString("content", r.Sistema);
            w.WriteEndObject();
            var msgs = r.Mensajes;
            for (var i = 0; i < msgs.Count;)
            {
                var m = msgs[i];
                if (EsInvocacionAsistente(m))
                {
                    w.WriteStartObject();
                    w.WriteString("role", "assistant");
                    w.WriteNull("content");
                    w.WriteStartArray("tool_calls");
                    while (i < msgs.Count && EsInvocacionAsistente(msgs[i]))
                    {
                        w.WriteStartObject();
                        w.WriteString("id", msgs[i].InvocacionId);
                        w.WriteString("type", "function");
                        w.WriteStartObject("function");
                        w.WriteString("name", msgs[i].NombreHerramienta);
                        w.WriteString("arguments", ArgumentosComoJson(msgs[i].Contenido).GetRawText());
                        w.WriteEndObject();
                        w.WriteEndObject();
                        i++;
                    }

                    w.WriteEndArray();
                    w.WriteEndObject();
                    continue;
                }

                w.WriteStartObject();
                if (m.Rol == RolMensaje.Herramienta)
                {
                    w.WriteString("role", "tool");
                    w.WriteString("tool_call_id", m.InvocacionId);
                }
                else
                {
                    w.WriteString("role", m.Rol == RolMensaje.Asistente ? "assistant" : "user");
                }

                w.WriteString("content", m.Contenido);
                w.WriteEndObject();
                i++;
            }

            w.WriteEndArray();
            if (r.Herramientas.Count > 0)
            {
                w.WriteStartArray("tools");
                foreach (var t in r.Herramientas)
                {
                    w.WriteStartObject();
                    w.WriteString("type", "function");
                    w.WriteStartObject("function");
                    w.WriteString("name", t.Nombre);
                    w.WriteString("description", t.Descripcion);
                    w.WritePropertyName("parameters");
                    t.EsquemaArgumentos.WriteTo(w);
                    w.WriteEndObject();
                    w.WriteEndObject();
                }

                w.WriteEndArray();
            }

            w.WriteEndObject();
        }

        return Encoding.UTF8.GetString(ms.ToArray());
    }

    protected override LlmResponse ParseResponse(string json)
    {
        using var doc = JsonDocument.Parse(json);
        var root = doc.RootElement;
        var message = root.GetProperty("choices")[0].GetProperty("message");
        var texto = message.TryGetProperty("content", out var c) && c.ValueKind == JsonValueKind.String
            ? c.GetString() ?? string.Empty
            : string.Empty;
        var invocaciones = new List<InvocacionPropuesta>();
        if (message.TryGetProperty("tool_calls", out var calls) && calls.ValueKind == JsonValueKind.Array)
        {
            foreach (var call in calls.EnumerateArray())
            {
                var fn = call.GetProperty("function");
                var args = fn.TryGetProperty("arguments", out var a) && a.ValueKind == JsonValueKind.String ? a.GetString() : null;
                JsonElement argumentos;
                try
                {
                    using var d = JsonDocument.Parse(string.IsNullOrWhiteSpace(args) ? "{}" : args);
                    argumentos = d.RootElement.Clone();
                }
                catch (JsonException)
                {
                    // Argumentos ilegibles: se entregan como cadena; el despachador los rechaza por esquema.
                    using var d = JsonDocument.Parse(JsonSerializer.Serialize(args));
                    argumentos = d.RootElement.Clone();
                }

                invocaciones.Add(new InvocacionPropuesta(
                    call.TryGetProperty("id", out var id) ? id.GetString() : null,
                    fn.GetProperty("name").GetString() ?? string.Empty,
                    argumentos));
            }
        }

        var usage = root.GetProperty("usage");
        return new LlmResponse(texto, invocaciones, new UsoTokens(Int(usage, "prompt_tokens"), Int(usage, "completion_tokens")));
    }

    private static int Int(JsonElement e, string name) =>
        e.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.Number ? v.GetInt32() : 0;
}

using TutorFlow.Application.Ports;

namespace TutorFlow.Application.Llm;

/// <summary>Resuelve el adaptador segun LLM_PROVIDER. Sin proveedor falso en ejecucion (SPEC A-11).</summary>
public static class LlmClientFactory
{
    public static ILlmClient Crear(
        LlmOptions options,
        HttpClient http,
        Action<string>? log = null,
        Func<TimeSpan, CancellationToken, Task>? delay = null)
    {
        ArgumentNullException.ThrowIfNull(options);
        ArgumentNullException.ThrowIfNull(http);
        return options.Provider switch
        {
            LlmProviders.Anthropic => new AnthropicLlmClient(http, options, log, delay),
            LlmProviders.OpenAiCompatible => new OpenAiCompatibleLlmClient(http, options, log, delay),
            _ => throw new LlmConfiguracionException(
                $"LLM_PROVIDER '{options.Provider}' no es valido. Valores admitidos: {LlmProviders.Anthropic} | {LlmProviders.OpenAiCompatible}."),
        };
    }
}

